public Product getProduct(Long id) {
    String key = "product:" + id;
    String json = redis.opsForValue().get(key);
    if (json != null) {
        return "NULL".equals(json) ? null : JSON.parseObject(json, Product.class);
    }
    String lockKey = "lock:" + key;
    Boolean locked = redis.opsForValue().setIfAbsent(lockKey, "1", Duration.ofSeconds(10));
    if (Boolean.TRUE.equals(locked)) {                 // 防击穿：只有一个线程查库
        try {
            Product p = productMapper.selectById(id);
            long ttl = 1800 + ThreadLocalRandom.current().nextInt(300); // 防雪崩：随机过期
            redis.opsForValue().set(key, p == null ? "NULL" : JSON.toJSONString(p),
                    Duration.ofSeconds(p == null ? 60 : ttl));          // 防穿透：缓存空值
            return p;
        } finally {
            redis.delete(lockKey);
        }
    }
    try { Thread.sleep(50); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
    return getProduct(id);                              // 简化重试，生产应限制次数
}

